// Realistic KMRL IntelliDocs mock data - 80 Employees, 200 Documents (1000-2000 words each), 80 Contracts, 25 Approvals, 20 Notifications

export interface MockComment {
  id: string;
  documentId: string;
  userName: string;
  userRole: string;
  userAvatar: string;
  content: string;
  createdAt: string;
}

export interface MockDocument {
  id: string;
  title: string;
  category: string;
  status: 'approved' | 'pending' | 'draft' | 'rejected';
  priority: 'low' | 'medium' | 'high' | 'critical';
  uploadedBy: string;
  department: string;
  createdAt: string;
  fileSize: number;
  mimeType: string;
  ocrStatus: string;
  description?: string;
  extractedText?: string;
  aiSummary?: {
    executiveSummary: string;
    keyFindings: string[];
    actionItems: string[];
    riskLevel: string;
    department: string;
    tags: string[];
  };
  comments?: MockComment[];
  tags?: string[];
  isDuplicate?: boolean;
  duplicateOfId?: string;
  duplicateOfTitle?: string;
  similarityScore?: number;
  assignedToUser?: string;
  assignedContractId?: string;
}

export interface MockEmployee {
  id: string;
  fullName: string;
  email: string;
  role: 'employee' | 'manager' | 'admin';
  department: string;
  assignedContractId: string;
  assignedContractName: string;
  assignedContractStatus: string;
  avatarInitials: string;
  badge: string;
}

export interface MockContract {
  id: string;
  contractNumber: string;
  title: string;
  vendor: string;
  department: string;
  assignedEmployeeName: string;
  assignedEmployeeEmail: string;
  valueAmount: number;
  startDate: string;
  expiryDate: string;
  status: 'active' | 'pending_approval' | 'expiring_soon' | 'under_renewal' | 'approved' | 'terminated';
  renewalNoticeDays: number;
  isExpiring: boolean;
}

export interface MockApproval {
  id: string;
  documentId: string;
  documentTitle: string;
  category: string;
  requestedBy: string;
  department: string;
  approver: string;
  status: 'pending' | 'approved' | 'rejected';
  dateRequested: string;
  priority: 'low' | 'medium' | 'high' | 'critical';
}

export interface MockNotification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'success' | 'alert';
  createdAt: string;
  read: boolean;
  link?: string;
}

